function getL(c) {
  const [r, g, b] = (c.match(/\d+/g) || [0,0,0]).slice(0, 3).map(v => {
    v = Number(v) / 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function getContrast(c1, c2) {
  const l1 = getL(c1), l2 = getL(c2);
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}
const el = document.getElementById('low-contrast-gray');
return getContrast(getComputedStyle(el).color, 'rgb(255, 255, 255)') >= 4.5;
